INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '填空', 3, '{"stem": "一个两位数，将它的十位数字和个位数字对调，得到的数比原来的数大27，这样的两位数可以是（ ）。", "options": null}', '14（答案不唯一，还有25、36、47、58、69）', '设十位a个位b，对调后10b+a-(10a+b)=9(b-a)=27→b-a=3。即个位比十位大3：14,25,36,47,58,69。', 'paper', '["拓展卷", "U1"]', '["paper_png/yg2_sx/p010"]', 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "计算\"55-3□\"，□里填（ ）时要退位。", "options": ["6,7,8,9", "5", "0,1,2,3,4"]}', '①', '55-3□要退位，个位5不够减，□必须>5，即6,7,8,9。答案①。', 'paper', '["拓展卷", "U1"]', '["paper_png/yg2_sx/p010"]', 0, 1);
